INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, example_sentence, synonyms, common_mistakes, ielts_context) VALUES ('tech-033', 'telemedicine service', '远程医疗服务', 'noun phrase', '6.5', 70, {"technology"}, {"reading","listening"}, {"access telemedicine services","telemedicine service platform","provide telemedicine services","telemedicine service delivery"}, 'Telemedicine services have greatly improved healthcare access for patients in rural and remote areas.', {"remote healthcare","virtual consultation","e-health service","digital healthcare"}, {"telemedicine 前缀 tele- 表示远距离，和 television/telescope 一样"}, 'Reading: healthcare technology; Listening Section 3: healthcare discussion');
