INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, example_sentence, synonyms, common_mistakes, ielts_context) VALUES ('tech-036', 'innovation hub', '创新中心', 'noun phrase', '6.0', 67, {"technology"}, {"reading","listening"}, {"global innovation hub","establish an innovation hub","technology and innovation hub","serve as an innovation hub"}, 'Silicon Valley remains the world''s most prominent innovation hub for technology startups.', {"tech hub","innovation center","technology cluster","startup ecosystem"}, {"hub 原意是轮毂，引申为中心/枢纽"}, 'Reading: business articles; Listening Section 3: business discussion');
