INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, example_sentence, synonyms, common_mistakes, ielts_context) VALUES ('tech-040', 'intellectual property', '知识产权', 'noun phrase', '6.5', 66, {"technology"}, {"writing","reading"}, {"protect intellectual property","intellectual property rights","intellectual property law","violate intellectual property"}, 'Protecting intellectual property is essential for encouraging creativity and innovation in the digital age.', {"IP","creative rights","proprietary knowledge","copyright and patent"}, {"property 不可数；intellectual property 也不可数"}, 'Writing Task 2: law / innovation; Reading: legal documents');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, example_sentence, synonyms, common_mistakes, ielts_context) VALUES ('tech-041', 'tech startup', '科技创业公司', 'noun phrase', '5.5', 64, {"technology"}, {"reading","speaking"}, {"found a tech startup","tech startup ecosystem","promising tech startup","invest in tech startups"}, 'The city has become a thriving hub for tech startups thanks to its supportive regulatory environment.', {"technology startup","tech venture","emerging tech company"}, {"startup 可连写也可 start-up，tech startup 更常用连写形式"}, 'Reading: business news; Speaking Part 2: career');
