INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, example_sentence, synonyms, common_mistakes, ielts_context) VALUES ('tech-048', 'hybrid work model', '混合办公模式', 'noun phrase', '6.0', 61, {"technology"}, {"speaking","writing"}, {"adopt a hybrid work model","hybrid work model benefits","implement a hybrid work model","shift to hybrid work models"}, 'Many companies have adopted a hybrid work model that combines remote and in-office work.', {"flexible work arrangement","blended work model","mixed-mode working","hybrid workplace model"}, {"hybrid 发音 /ˈhaɪbrɪd/，不是 high-brid"}, 'Speaking Part 3: work trends; Writing Task 2: future of work');
