INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, example_sentence, synonyms, common_mistakes, ielts_context) VALUES ('work-010', 'corporate culture', '企业文化', 'noun phrase', '6.5', 92, {"work"}, {"reading","writing"}, {"strong corporate culture","shape corporate culture","toxic corporate culture","corporate culture transformation"}, 'A healthy corporate culture encourages innovation and open communication among staff.', {"organizational culture","company culture","business culture"}, {"corporate 的发音 /ˈkɔːpərət/，重音在第一音节"}, 'Reading: business articles; Writing Task 2: management');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, example_sentence, synonyms, common_mistakes, ielts_context) VALUES ('work-011', 'salary negotiation', '薪资谈判', 'noun phrase', '6.0', 90, {"work"}, {"speaking","listening"}, {"engage in salary negotiation","successful salary negotiation","salary negotiation skills","during salary negotiation"}, 'Many candidates feel uncomfortable with salary negotiation and accept the first offer they receive.', {"pay negotiation","wage bargaining","compensation negotiation"}, {"negotiation 拼写注意 ti 不是 ci"}, 'Speaking Part 3: workplace / career; Listening Section 3: job interview discussion');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, example_sentence, synonyms, common_mistakes, ielts_context) VALUES ('work-012', 'performance evaluation', '绩效评估', 'noun phrase', '6.5', 90, {"work"}, {"reading","writing"}, {"undergo performance evaluation","annual performance evaluation","conduct a performance evaluation","performance evaluation system"}, 'Regular performance evaluations provide employees with valuable feedback for improvement.', {"performance review","performance appraisal","performance assessment"}, {"evaluation 的动词是 evaluate，去 e 加 ion"}, 'Reading: HR management; Writing Task 2: workplace practices');
